// Generated by Cypress Author on 2026-10-22
//
// REN 01 · REN 02 · REN 04 · REN 05 · REN 07 · REN 08 (servidor) — Plano_de_Testes_QA_MatchWallet.md
// §7 (docs-test/areas/ren.md). Cada teste usa uma CARTEIRA PRÓPRIA (criada e desativada aqui) para
// lançar rentabilidade em competências que só ela tem; o admin real só executa as ações de equipe.
//
// Limites: a virada de ano de `/minha-carteira/performance` (mês atual e acumulado do ano) depende
// do relógio do servidor e só é conferida na UI com relógio simulado (`stubbed/rentabilidade-cliente`).
// Aqui REN 08 prova o que dá para controlar: o acumulado anual do lançamento reinicia em janeiro e
// um mês sem lançamento não vira linha zerada.

import { competenciaRelativa } from '../../support/commands/fluxos'

type Valores = {
  rentabilidadeMes: number
  rentabilidadeAcumuladaAno: number
  cdiMes: number
  ibovMes: number
}

interface Lancamento extends Valores {
  mesReferencia?: string
  avisos?: string[]
  acumuladoCalculado?: number
}

interface Serie {
  mesReferencia: string
  rentabilidade: number
  cdi: number
  ibov: number
  percentualCdi: number | null
}

interface Historico {
  serie: Serie[]
  acumulado: { carteira: number; cdi: number; ibov: number }
}

const carteirasCriadas: string[] = []
const VALORES: Valores = {
  rentabilidadeMes: 1.5,
  rentabilidadeAcumuladaAno: 6.25,
  cdiMes: 1,
  ibovMes: -2,
}
const RECUSADO = [400, 422]

function comoAdmin() {
  cy.clearCookies()
  cy.loginReal('admin')
}

function novaCarteira() {
  return cy.criarCarteiraDeTeste().then((id) => {
    carteirasCriadas.push(id)
    return id
  })
}

function lancar(
  carteiraId: string,
  mesReferencia: unknown,
  valores: Record<string, unknown> = VALORES,
) {
  return cy.apiRequest<Lancamento>({
    method: 'POST',
    url: `/carteiras/${carteiraId}/rentabilidade`,
    body: { mesReferencia, ...valores },
    failOnStatusCode: false,
  })
}

function corrigir(carteiraId: string, mesReferencia: string, valores: Record<string, unknown>) {
  return cy.apiRequest<Lancamento>({
    method: 'PUT',
    url: `/carteiras/${carteiraId}/rentabilidade/${mesReferencia}`,
    body: valores,
    failOnStatusCode: false,
  })
}

function historico(carteiraId: string) {
  return cy
    .apiRequest<Historico>({
      method: 'GET',
      url: `/carteiras/${carteiraId}/historico-performance?periodoMeses=60`,
    })
    .its('body')
}

/** Lança (ou corrige, se já existir) e reconcilia o acumulado do ano com o composto pelo servidor. */
function lancarReconciliado(carteiraId: string, mesReferencia: string, valores: Valores) {
  lancar(carteiraId, mesReferencia, valores).then(({ status }) => {
    if (status === 409) corrigir(carteiraId, mesReferencia, valores)
  })
  corrigir(carteiraId, mesReferencia, valores).then(({ body }) => {
    if (body.avisos?.includes('ACUMULADO_DIVERGENTE')) {
      corrigir(carteiraId, mesReferencia, {
        ...valores,
        rentabilidadeAcumuladaAno: body.acumuladoCalculado,
      })
        .its('body.avisos')
        .should('not.exist')
    }
  })
}

describe('Plano QA · Rentabilidade no servidor', () => {
  after(() => {
    comoAdmin()
    for (const id of carteirasCriadas) cy.desativarCarteira(id)
  })

  it('REN 01 · lançamento 1,50 / 6,25 / 1,00 / -2,00 → persistido na carteira e competência certas, na escala percentual, sem 150%', () => {
    const mes = competenciaRelativa(-1)
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      lancar(carteiraId, mes).then(({ status, body }) => {
        expect(status).to.eq(201)
        expect(body.mesReferencia).to.eq(mes)
        expect(body.rentabilidadeMes).to.eq(1.5)
        expect(body.rentabilidadeAcumuladaAno).to.eq(6.25)
        expect(body.cdiMes).to.eq(1)
        expect(body.ibovMes).to.eq(-2)
        // Acumulado informado (6,25) diverge do composto de um único mês (1,5): é aviso, não erro.
        expect(body.avisos).to.include('ACUMULADO_DIVERGENTE')
        expect(body.acumuladoCalculado).to.be.closeTo(1.5, 0.0001)
      })

      historico(carteiraId).then(({ serie }) => {
        expect(serie).to.have.length(1)
        expect(serie[0].mesReferencia).to.eq(mes)
        expect(serie[0].rentabilidade).to.eq(1.5)
        expect(serie[0].cdi).to.eq(1)
        expect(serie[0].ibov).to.eq(-2)
      })
    })
  })

  it('REN 02 · carteira ÷ CDI × 100 → 150% para 1,50/1,00 e dízima coerente para 1/3', () => {
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      lancar(carteiraId, competenciaRelativa(-2), { ...VALORES, rentabilidadeAcumuladaAno: 1.5 })
        .its('status')
        .should('eq', 201)
      lancar(carteiraId, competenciaRelativa(-1), {
        rentabilidadeMes: 1,
        rentabilidadeAcumuladaAno: 2.5,
        cdiMes: 3,
        ibovMes: 0,
      })
        .its('status')
        .should('eq', 201)

      historico(carteiraId).then(({ serie }) => {
        const [primeira, segunda] = serie
        expect(primeira.percentualCdi).to.be.closeTo(150, 0.05)
        // A mesma fórmula da prévia da tela: arredondada a 1 casa, 33,3.
        expect(segunda.percentualCdi).to.be.closeTo(33.3, 0.05)
      })
    })
  })

  it('REN 04 · aceita negativo, zero e 4 casas; recusa 5 casas, texto, vírgula e valores fora dos limites → sem gravar nada ao recusar', () => {
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      const aceitos = [
        { mes: '2024-01', rentabilidadeMes: -0.5 },
        { mes: '2024-02', rentabilidadeMes: 0 },
        { mes: '2024-03', rentabilidadeMes: 1.2345 },
        { mes: '2024-04', rentabilidadeMes: -100 },
        { mes: '2024-05', rentabilidadeMes: 1000 },
      ]
      for (const { mes, rentabilidadeMes } of aceitos) {
        lancar(carteiraId, mes, { ...VALORES, rentabilidadeMes }).then(({ status, body }) => {
          expect(status, `rentabilidade ${rentabilidadeMes}`).to.eq(201)
          // Precisão preservada, sem arredondar em silêncio.
          expect(body.rentabilidadeMes).to.eq(rentabilidadeMes)
        })
      }

      const recusados: Array<[string, Record<string, unknown>]> = [
        ['5 casas decimais', { rentabilidadeMes: 1.23456 }],
        ['vírgula como texto', { rentabilidadeMes: '1,5' }],
        ['ponto como texto', { rentabilidadeMes: '1.5' }],
        ['letras', { rentabilidadeMes: 'abc' }],
        ['vazio', { rentabilidadeMes: '' }],
        ['nulo', { rentabilidadeMes: null }],
        ['acima do máximo (1000,01)', { rentabilidadeMes: 1000.01 }],
        ['abaixo do mínimo (-100,01)', { rentabilidadeMes: -100.01 }],
        ['CDI acima de 100', { cdiMes: 100.01 }],
        ['CDI abaixo de -100', { cdiMes: -100.01 }],
        ['Ibovespa acima de 100', { ibovMes: 100.01 }],
      ]
      for (const [rotulo, alteracao] of recusados) {
        lancar(carteiraId, '2024-12', { ...VALORES, ...alteracao })
          .its('status', { log: false })
          .should('be.oneOf', RECUSADO)
        cy.log(`recusado: ${rotulo}`)
      }

      historico(carteiraId).then(({ serie }) => {
        expect(serie.map((l) => l.mesReferencia)).to.deep.eq(aceitos.map((a) => a.mes))
        expect(serie.some((l) => l.mesReferencia === '2024-12')).to.eq(false)
      })
    })
  })

  it('REN 05 · mês 13/00/vazio/futuro, repetição e correção → validado no servidor, 409 sem alterar e PUT corrige sem criar linha', () => {
    const mes = competenciaRelativa(-1)
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      for (const invalida of ['2026-13', '2026-00', '', '2026-1', 'abcd-ef', '26-10', null]) {
        lancar(carteiraId, invalida).its('status', { log: false }).should('be.oneOf', RECUSADO)
      }
      // Competência futura é regra de negócio, não de formato.
      lancar(carteiraId, competenciaRelativa(1)).its('status').should('eq', 422)

      lancar(carteiraId, mes).its('status').should('eq', 201)

      // Repetir a mesma competência: 409 e o lançamento original segue como estava.
      lancar(carteiraId, mes, { ...VALORES, rentabilidadeMes: 9 })
        .its('status')
        .should('eq', 409)
      historico(carteiraId).then(({ serie }) => {
        expect(serie).to.have.length(1)
        expect(serie[0].rentabilidade).to.eq(1.5)
      })

      // A correção é pelo PUT: atualiza a mesma linha.
      corrigir(carteiraId, mes, { ...VALORES, rentabilidadeMes: 2 })
        .its('status')
        .should('eq', 200)
      historico(carteiraId).then(({ serie }) => {
        expect(serie).to.have.length(1)
        expect(serie[0].rentabilidade).to.eq(2)
      })

      // PUT em competência sem lançamento ou malformada não cria nada.
      corrigir(carteiraId, competenciaRelativa(-2), VALORES).its('status').should('eq', 404)
      corrigir(carteiraId, '2026-13', VALORES).its('status').should('be.oneOf', RECUSADO)
      historico(carteiraId).its('serie').should('have.length', 1)
    })
  })

  it('REN 07 · lançamento em M com cliente vinculado → histórico, desempenho e painel iguais, sem dados de outra carteira', () => {
    const mes = competenciaRelativa()
    const valores: Valores = {
      rentabilidadeMes: 1.5,
      rentabilidadeAcumuladaAno: 1.5,
      cdiMes: 1,
      ibovMes: -2,
    }

    cy.criarUsuarioDescartavel().then((conta) => {
      cy.clearCookies()
      cy.loginComo(conta)
      cy.avaliarSuitability(conta, 'maior').then((resultado) => {
        const carteiraId = resultado.carteiraRecomendada?.id as string
        expect(carteiraId, 'carteira vinculada').to.be.a('string')

        // Equipe: lança M na carteira do cliente e, na outra carteira, valores bem diferentes.
        comoAdmin()
        lancarReconciliado(carteiraId, mes, valores)
        novaCarteira().then((outraId) => {
          lancar(outraId, mes, {
            rentabilidadeMes: 9.99,
            rentabilidadeAcumuladaAno: 9.99,
            cdiMes: 1,
            ibovMes: 7.77,
          })
            .its('status')
            .should('eq', 201)
        })

        // Histórico administrativo da carteira.
        historico(carteiraId).then(({ serie }) => {
          const linha = serie.find((l) => l.mesReferencia === mes)
          expect(linha?.rentabilidade).to.eq(1.5)
          expect(linha?.cdi).to.eq(1)
          expect(linha?.ibov).to.eq(-2)
        })

        // Cliente: desempenho e painel batem com o histórico.
        cy.clearCookies()
        cy.loginComo(conta)
        cy.apiRequest<{
          mesAtual: {
            competencia: string
            rentabilidade: number
            cdi: number
            percentualCdi: number
          } | null
        }>({ method: 'GET', url: '/minha-carteira/performance' }).then(({ body }) => {
          expect(body.mesAtual?.competencia).to.eq(mes)
          expect(body.mesAtual?.rentabilidade).to.eq(1.5)
          expect(body.mesAtual?.cdi).to.eq(1)
          expect(body.mesAtual?.percentualCdi).to.be.closeTo(150, 0.05)
          expect(JSON.stringify(body)).not.to.contain('9.99')
        })
        cy.apiRequest<{ carteira: { id: string; rentabilidadeUltimoMes: number } }>({
          method: 'GET',
          url: '/dashboard/investidor',
        }).then(({ body }) => {
          expect(body.carteira.id).to.eq(carteiraId)
          expect(body.carteira.rentabilidadeUltimoMes).to.eq(1.5)
        })

        // Mesmos números na tela do cliente.
        cy.visit('/')
        cy.contains('[data-slot="kpi-card"]', 'Rentabilidade do mês').should(
          'contain.text',
          '+1,50 %',
        )
        cy.visit('/carteira')
        cy.contains('[data-slot="kpi-card"]', 'Mês')
          .should('contain.text', '+1,50 %')
          .and('contain.text', 'Ibov -2,00 %')
        cy.contains('9,99').should('not.exist')
      })
    })
  })

  it('REN 08 · dezembro, fevereiro e janeiro → acumulado anual reinicia em janeiro e mês sem lançamento não vira linha zerada', () => {
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      // Dezembro de 2024 e fevereiro de 2025 (sem janeiro no meio).
      lancar(carteiraId, '2024-12', {
        ...VALORES,
        rentabilidadeMes: 1.5,
        rentabilidadeAcumuladaAno: 1.5,
      })
        .its('body.avisos')
        .should('not.exist')
      lancar(carteiraId, '2025-02', {
        ...VALORES,
        rentabilidadeMes: 1,
        rentabilidadeAcumuladaAno: 1,
      })
        .its('body.avisos')
        .should('not.exist')

      // Janeiro de 2025 reinicia o ano: o acumulado correto é só o de janeiro (2,00).
      lancar(carteiraId, '2025-01', {
        ...VALORES,
        rentabilidadeMes: 2,
        rentabilidadeAcumuladaAno: 2,
      }).then(({ status, body }) => {
        expect(status).to.eq(201)
        // Com fevereiro já lançado, o composto do ano até janeiro continua sendo só janeiro.
        expect(body.avisos, 'janeiro não herda o acumulado de dezembro').to.be.oneOf([
          undefined,
          [],
        ])
      })

      // Fevereiro com o acumulado "arrastado" de dezembro (soma entre anos) é apontado como divergente.
      corrigir(carteiraId, '2025-02', {
        ...VALORES,
        rentabilidadeMes: 1,
        rentabilidadeAcumuladaAno: 4.55,
      }).then(({ body }) => {
        expect(body.avisos).to.include('ACUMULADO_DIVERGENTE')
        // (1,02 × 1,01 − 1) × 100 = 3,02: só janeiro + fevereiro de 2025.
        expect(body.acumuladoCalculado).to.be.closeTo(3.02, 0.01)
      })

      // Série em ordem cronológica, com os três meses e nenhuma linha inventada.
      historico(carteiraId).then(({ serie }) => {
        expect(serie.map((l) => l.mesReferencia)).to.deep.eq(['2024-12', '2025-01', '2025-02'])
      })
    })
  })

  it('REN 08 · mês sem lançamento entre dois lançados → ausente da série, sem retorno zerado', () => {
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      lancar(carteiraId, '2024-10', VALORES).its('status').should('eq', 201)
      lancar(carteiraId, '2024-12', VALORES).its('status').should('eq', 201)

      historico(carteiraId).then(({ serie }) => {
        expect(serie.map((l) => l.mesReferencia)).to.deep.eq(['2024-10', '2024-12'])
        expect(serie.some((l) => l.mesReferencia === '2024-11')).to.eq(false)
      })
    })
  })
})
